<?php
declare(strict_types=1); namespace App\Services\Personnel;
use RuntimeException; use ZipArchive;
class SimpleXlsxService
{
 public function read(string $path):array{$z=new ZipArchive;if($z->open($path)!==true)throw new RuntimeException('File tidak dapat dibaca atau rusak.');$shared=[];$sx=$z->getFromName('xl/sharedStrings.xml');if($sx){$xml=simplexml_load_string($sx);foreach($xml->si as $si)$shared[]=trim(implode('',array_map('strval',$si->xpath('.//t'))));}$workbook=simplexml_load_string((string)$z->getFromName('xl/workbook.xml'));$rels=simplexml_load_string((string)$z->getFromName('xl/_rels/workbook.xml.rels'));$map=[];foreach($rels->Relationship as $rel)$map[(string)$rel['Id']]=(string)$rel['Target'];$workbook->registerXPathNamespace('r','http://schemas.openxmlformats.org/officeDocument/2006/relationships');$sheets=[];foreach($workbook->sheets->sheet as $sheet){$a=$sheet->attributes('http://schemas.openxmlformats.org/officeDocument/2006/relationships');$target=$map[(string)$a['id']]??'';$xml=simplexml_load_string((string)$z->getFromName('xl/'.ltrim($target,'/')));$rows=[];foreach($xml->sheetData->row as $row){$values=[];foreach($row->c as $c){$ref=(string)$c['r'];preg_match('/[A-Z]+/',$ref,$m);$col=$this->columnNumber($m[0]);$type=(string)$c['t'];$v=(string)$c->v;if($type==='s')$v=$shared[(int)$v]??'';elseif($type==='inlineStr')$v=implode('',array_map('strval',$c->xpath('.//t')));$values[$col]=$v;}$rows[(int)$row['r']]=$values;}$sheets[(string)$sheet['name']]=$rows;}$z->close();return $sheets;}
 public function write(array $rows,string $path):void{$z=new ZipArchive;$z->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE);$esc=fn($v)=>htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8');$sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><sheetData>';foreach(array_values($rows) as $ri=>$row){$n=$ri+1;$sheet.='<row r="'.$n.'">';foreach(array_values($row) as $ci=>$v){$ref=$this->columnName($ci+1).$n;$sheet.='<c r="'.$ref.'" t="inlineStr" s="'.($ri===0?1:0).'"><is><t>'.$esc($v).'</t></is></c>';}$sheet.='</row>';}$last=$this->columnName(count($rows[0]??[]));$sheet.='</sheetData><autoFilter ref="A1:'.$last.count($rows).'"/></worksheet>';$files=['[Content_Types].xml'=>'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>','_rels/.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml'=>'<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Data Personalia" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>','xl/styles.xml'=>'<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font/><font><b/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf/><xf fontId="1" applyFont="1"/></cellXfs></styleSheet>','xl/worksheets/sheet1.xml'=>$sheet];foreach($files as $name=>$body)$z->addFromString($name,$body);$z->close();}
 private function columnNumber(string $s):int{$n=0;foreach(str_split($s) as $c)$n=$n*26+ord($c)-64;return $n;} private function columnName(int $n):string{$s='';while($n){$n--;$s=chr(65+$n%26).$s;$n=intdiv($n,26);}return $s;}
}
